css:
/* minimal overrides */
[data-layout="minimal"] .sidebar { display: none !important; }
[data-layout="minimal"] .terminal-panel,
[data-layout="minimal"] .status-bar { display: none !important; }
[data-layout="minimal"] .preview-panel { border-top: 1px solid var(--border); }
[data-layout="minimal"] .window-bar { height: auto; padding: 12px 22px; flex-wrap: wrap; }
[data-layout="minimal"] .preview-content { padding: 56px 48px; }
[data-layout="minimal"] .preview-content h1 { font-size: 2.2rem; }
